example:
// pay.bynk
context pay

service charge {
    on call(amount: Int) -> Effect[Int] by Caller {
        Effect.pure(amount)
    }
}

// shop.bynk
context shop

consumes pay

service checkout {
    on call() -> Effect[Int] by Caller {
        pay.charge(1, 2)         // ✗ `charge` takes one argument
    }
}

service checkout {
    on call() -> Effect[Int] by Caller {
        pay.charge(1)            // ✓ one argument for `amount`
    }
}
